const key = $json.templateContext?.templateKey ?? "unsupported";
const templates = {
  confirmation_prompt: $json.templateContext?.confirmationPrompt ?? "Necesito tu confirmación explícita para continuar.",
  confirmation_cancelled: "Entendido. No hice ningún cambio en tu reserva.",
  availability_result: "Ya revisé la disponibilidad. En seguida te comparto las opciones confirmadas.",
  create_result: "Tu solicitud de reserva quedó registrada. Te comparto el detalle enseguida.",
  update_result: "Tu cambio quedó procesado. Revisa por favor el detalle actualizado.",
  cancel_result: "La cancelación quedó registrada correctamente.",
  list_result: "Estas son las reservas asociadas a tu número verificado.",
  detail_result: "Aquí tienes el detalle de tu reserva.",
  occasionCatalog_result: "Estas son las ocasiones disponibles para tu reserva.",
  unsupported: "No pude resolver esa solicitud de forma segura. Te voy a pasar con una persona del restaurante.",
  handoff_result: "Te voy a comunicar con una persona del restaurante para continuar por este mismo WhatsApp."
};
return [{ json: { ...$json, outboundMessage: templates[key] ?? templates.unsupported } }];
